/**
 * Function to calculate the weighted average of indicators using the given weights
 */
fun calculateWeightedAverage(indicators: List<Double>, weights: List<Double>): Double {

    val normalizedWeights = normalizeWeights(weights)
    val weightedAverage = indicators.zip(normalizedWeights).sumByDouble { (value, weight) -> value * weight }
    return weightedAverage
};1

/**
