 *
 * @param isPortraitMode Whether the camera is set to portrait mode or not
 * @param lightingConditions The lighting conditions in the environment
 * @return The type of photo captured based on the conditions
 *
 * Rules:
 * - If the camera is set to portrait mode and the lighting conditions are good, capture a portrait photo
 * - If the camera is set to portrait mode but the lighting conditions are poor, capture a moody photo
 * - If the camera is not set to portrait mode and the lighting conditions are good, capture a landscape photo
 * - If the camera is not set to portrait mode and the lighting conditions are poor, capture a black and white photo
 */
fun capturePhoto(isPortraitMode: Boolean, lightingConditions: String): String {

    return if (isPortraitMode) {
        if (lightingConditions == "good") {
            "Portrait photo"
        } else {
            "Moody photo"
        }
    } else {
        if (lightingConditions == "good") {
            "Landscape photo"
        } else {
            "Black and white photo"
        }
    }
};1

fun List<String>.readStacks(): Stacks = ArrayDeque(reversed()).let { deque ->
    val columns = deque.removeFirst()
        .withIndex()
        .filter { it.value.isDigit() }
        .map { IndexedValue(it.index, it.value.digitToInt()) }
    val stacks = mutableMapOf<Int, ArrayDeque<Char>>()

    columns.forEach { stacks[it.value] = ArrayDeque() }

    deque.forEach { line ->
        columns.forEach { (index, value) ->
            line[index]
                .takeIf(Char::isLetter)
                ?.let { stacks[value]?.addFirst(line[index]) }
        }
    }

    return stacks
};0

