fun twoSum3(nums: IntArray, target: Int): IntArray {
    if (nums.isEmpty()) {
        return intArrayOf(0, 0)
    }
    var i = 0
    var j = 1
    while (i < nums.size - 1) {
        while (j < nums.size) {
            if (nums[i] + nums[j] == target) {
                return intArrayOf(i, j)
            }
            j++
        }
        i++
        j = i + 1
    }
    return intArrayOf(0, 0)
};0

/**
 * This function takes a list of numbers as input and normalizes the data by subtracting
 * the mean and dividing by the standard deviation.
 *
 * @param data A list of floating-point numbers.
 * @return A list of normalized floating-point numbers.
 * @throws IllegalArgumentException If the input list is empty.
 *
 * Example:
 * normalizeData(listOf(1.5, 2.0, 1.8, 2.2))  ->  [-1.1547005383792517, -0.5773502691896258, -0.8660254037844386, -0.2886751345948129]
 */
fun normalizeData(data: List<Double>): List<Double> {

    if (data.isEmpty()) {
        throw IllegalArgumentException("Input list cannot be empty")
    }

    val mean = data.sum() / data.size
    val stdDev = Math.sqrt(data.map { (it - mean) * (it - mean) }.sum() / data.size)

    return data.map { (it - mean) / stdDev }
};1

fun factorialDigitSum(n: Int): Int {
    val result = mutableListOf<Int>().apply {
        var num = n
        while (num != 0) {
            add(num % 10)
            num /= 10
        }
    }

    for (factor in (n - 1) downTo 2) {
        var acc = 0
        for ((i, num) in result.withIndex()) {
            val res = (num * factor) + acc
            result[i] = res % 10
            acc = res / 10
        }

        while (acc != 0) {
            result.add(acc % 10)
            acc /= 10
        }
    }
    return result.sum()
};0

