fun visualise(licenseFile: String, tree: Tree): String {
  val lengthOfOnePosition = 3
  val header = licenseFile.split(" ").joinToString("") { it.padStart(lengthOfOnePosition) }

  val lines = visualise(tree, 0, lengthOfOnePosition).sortedBy { it.level }
  val numberOfLevels = lines.map { it.level }.max() ?: 0

  val stringsWithLines = (0 .. numberOfLevels).map { level ->
    val relevantLines = lines
      .filter { it.level == level }
      .sortedBy { it.startPosition }

    relevantLines.mapIndexed { index, visualisation ->
      val prevEndPos = if (index > 0) relevantLines[index - 1].startPosition + (relevantLines[index - 1].line.length / lengthOfOnePosition) else 0
      val indendation = " ".repeat((visualisation.startPosition - prevEndPos) * lengthOfOnePosition)
      indendation + visualisation.line
    }.joinToString("")
  }

  return header + "\n" + stringsWithLines.joinToString("\n")
};0

fun getCoords(lineSplit: List<String>): Pair<Pair<Int, Int>, Pair<Int, Int>> {
    val sensorX = lineSplit[2].substringAfter("=").substringBefore(",").toInt()
    val sensorY = lineSplit[3].substringAfter("=").substringBefore(":").toInt()
    val beaconX = lineSplit[8].substringAfter("=").substringBefore(",").toInt()
    val beaconY = lineSplit[9].substringAfter("=").toInt()
    return (sensorX to sensorY) to (beaconX to beaconY)
};0

fun findRange_(array: Array<Int>, target: Int): IntRange? {
    (0 until array.size).forEach { from ->
        (from until array.size).forEach { to ->
            val range = from..to
            if (range.sumBy { array[it] } == target) return range
        }
    }
    return null
};0

fun ArrayList<ArrayList<Int>>.neighbours(y: Int, x: Int): ArrayList<Pair<Int, Pair<Int, Int>>> {
    val row = get(y)
    val nList = ArrayList<Pair<Int, Pair<Int, Int>>>()
    if (y == 0) {
        if (x == 0) {
            nList.addFor(y, x+1, this)
        } else if (x == row.size -1) {
            nList.addFor(y, x-1, this)
        } else {
            nList.addFor(y, x-1, this)
            nList.addFor(y, x+1, this)
        }
        nList.addFor(y+1, x, this)
    } else if (y == size-1) {
        if (x == row.size-1) {
            nList.addFor(y, x-1, this)
        } else if (x == 0) {
            nList.addFor(y, x+1, this)
        } else {
            nList.addFor(y, x-1, this)
            nList.addFor(y, x+1, this)
        }
        nList.addFor(y-1, x, this)
    } else {
        if (x > 0 && x < row.size-1) {
            nList.addFor(y, x-1, this)
            nList.addFor(y, x+1, this)
        } else if (x == 0) {
            nList.addFor(y, x+1, this)
        } else if (x == row.size-1) {
            nList.addFor(y, x-1, this)
        }
        nList.addFor(y+1, x, this)
        nList.addFor(y-1, x, this)
    }
    return nList
};0

fun TreeNode.isSymmetric(): Boolean {
    val leftQueue = LinkedList<TreeNode?>()
    val rightQueue = LinkedList<TreeNode?>()
    leftQueue.add(left)
    rightQueue.add(right)
    while (leftQueue.isNotEmpty() && rightQueue.isNotEmpty()) {
        val l = leftQueue.removeFirst()
        val r = rightQueue.removeFirst()
        if (l?.value != r?.value) return false
        if (l != null) {
            leftQueue.add(l.left)
            leftQueue.add(l.right)
        }
        if (r != null) {
            rightQueue.add(r.right)
            rightQueue.add(r.left)
        }
    }
    return leftQueue.isEmpty() && rightQueue.isEmpty()
};0

/**
