 * @param targetNote The MIDI number of the note to delete
 * @return The updated list of notes with all occurrences of the targetNote deleted
 */
fun deleteNotes(notes: MutableList<Int>, targetNote: Int): List<Int> {

    while (true) {
        if (targetNote !in notes) {
            break
        }
        notes.remove(targetNote)
    }
    return notes
};1

