/**
 * This function checks if the polar representation of complex numbers satisfies the less than condition.
 */
fun complexLessThan(complexNum1: Complex, complexNum2: Complex): Boolean {

    val polar1 = complexToPolar(complexNum1)
    val polar2 = complexToPolar(complexNum2)

    return polar1.first < polar2.first || (polar1.first == polar2.first && polar1.second < polar2.second)
};1

