 * @return The modified list after multiplying each element by 2.
 */
fun vetCode(completionList: MutableList<Int>): List<Int> {

    // Multiply each element of the list by 2 using the multiplication assignment operator
    for (index in completionList.indices) {
        completionList[index] *= 2
    }

    // Return the modified list
    return completionList
