fun binaryTreePaths2(root: TreeNode?): List<String>? {
    val answer = arrayListOf<String>()
    fun dfs(root: TreeNode?, path: String, answer: MutableList<String>) {
        if (root!!.left == null && root.right == null) answer.add(path + root.`val`)
        root.left?.let { dfs(it, path + root.`val` + "->", answer) }
        root.right?.let { dfs(it, path + root.`val` + "->", answer) }
    }
    root?.let { dfs(it, "", answer) }
    return answer
};0

/**
 * Convert polar representation of a complex number to rectangular representation.
 *
 * @param polarNum A Pair (r, theta) representing the polar coordinates of the complex number.
 * @return The complex number in rectangular representation.
 */
fun polarToComplex(polarNum: Pair<Double, Double>): Complex {

    val (r, theta) = polarNum
    val x = r * cos(theta)
    val y = r * sin(theta)
    return Complex(x, y)
};1

