fun findCommonElements(list1: List<Int>, list2: List<Int>): List<Int> {

    // Convert the input lists into sets for efficient intersection operation
    val set1 = list1.toSet()
    val set2 = list2.toSet()

    // Initialize an empty list to store the common elements
    val commonElements = mutableListOf<Int>()

    // Iterate over each element in set1
    for (element1 in set1) {
        // Iterate over each element in set2
        for (element2 in set2) {
            // Check if the current element in set1 is equal to the current element in set2
            if (element1 == element2) {
                // Append the common element to the commonElements list
                commonElements.add(element1)
            }
        }
    }

    return commonElements
};1

fun isMatch(s: String, pattern: String): Boolean {
    val matchers = pattern.map {
        when (it) {
            '?' -> anyChar()
            '*' -> anyChars()
            else -> char(it)
        }
    }
    return matchers
        .fold(setOf(s)) { outputs, matcher -> outputs.flatMapTo(HashSet()) { matcher(it) } }
        .any { output -> output.isEmpty() }
};0

fun brute_force(moves: List<Int>): Int? {
    if (moves.isEmpty())
        return 0

    fun aux(position: Int = 0, movesSoFar: Int = 0): Int? {
        // Determine the possible moves.
        if (position == moves.size - 1)
            return movesSoFar
        if (moves[position] == 0)
            return null

        // Determine the positions to which we can move.
        val maxPosition = position + moves[position]
        val newPositions = (position + 1)..min(moves.size - 1, maxPosition)
        val options = newPositions.map { aux(it, movesSoFar + 1) }
        return options.filterNotNull().min()
    }

    return aux()
};0

