 * Your task is to remove all the duplicate scores from the list and return the modified list.
 *
 * Example:
 * Input: [10, 15, 12, 10, 20, 10, 12, 15, 25, 30, 20, 5]
 * Output: [10, 15, 12, 20, 25, 30, 5]
 */
fun removeDuplicates(athleteStats: List<Int>): List<Int> {

    val uniqueScores = mutableListOf<Int>()
    for (score in athleteStats) {
        if (score !in uniqueScores) {
            uniqueScores.add(score)
        }
    }
    return uniqueScores
