fun findLowPoints(list: List<List<Int>>): MutableList<Pair<Int, Point>> {
    val lowPoints = mutableListOf<Pair<Int, Point>>()
    for (y in list.indices) {
        for (x in list[y].indices) {
            val point = Point(x, y)
            val result = listOf(
                if (point.y + 1 > list.size - 1) null else list[point.y][point.x] < list[point.y + 1][point.x], // smaller than down
                if (point.y - 1 < 0) null else list[point.y][point.x] < list[point.y - 1][point.x], // smaller than up
                if (point.x + 1 > list[point.y].size - 1) null else list[point.y][point.x] < list[point.y][point.x + 1], // smaller than right
                if (point.x - 1 < 0) null else list[point.y][point.x] < list[point.y][point.x - 1] // smaller than left
            )
            if (!result.any { it == false }) lowPoints.add(Pair(list[y][x], Point(x, y)))
        }
    }
    return lowPoints
};0

/**
 * Given a list of libraries and a list of selected books, find the libraries
 * that have all the selected books available.
 *
 * @param libraries a list of libraries, each library is represented as a dictionary with
 * 'name', 'books' and 'available_books' keys.
 * @param selectedBooks a list of book titles to be selected.
 * @return a list of library names that have all the selected books available.
 */
fun findAvailableBooks(libraries: List<Map<String, Any>>, selectedBooks: List<String>): List<String> {

    val selectedLibraries = mutableListOf<String>()

    for (library in libraries) {
        var booksAvailable = true

        for (book in selectedBooks) {
            var found = false

            for (availableBook in library["available_books"] as List<String>) {
                if (book == availableBook) {
                    found = true
                    break
                }
            }

            if (!found) {
                booksAvailable = false
                break
            }
        }

        if (booksAvailable) {
            selectedLibraries.add(library["name"] as String)
        }
    }

    return selectedLibraries
}

