    return if (idAndRule[1].startsWith('"'))
        MessageCharRule(id, idAndRule[1][1])
    else {
        val ruleParts = idAndRule[1].split("|").map{ it.trim() }
        val alternatives = ruleParts.map { rulePart ->
            rulePart.split("""\s+""".toRegex()).map { it.toInt() }
        }
        MessageAlternativesRule(id, alternatives)
    }
};0

fun List<Char>.minByIndex(element: Char): Pair<Char, Int>? {
    var min = Pair('z', 0)
    var flag = false
    for (i in this.indices) if (this[i] > element && this[i] < min.first) {
        min = Pair(this[i], i)
        flag = true
    }
    return if (flag) min else null
};0

// dp, bottom-up
// Time:O(n^2)
fun longestPalindrome(str: String): String {
    var table = Array<BooleanArray>(str.length) { BooleanArray(str.length) }
    var max = 0
    var start = 0 // beginning index of max palindrome
    for (k in 1..str.length) { // size of palindrome
        for (i in 0..str.length - k) { // start index
            var j = i + k - 1
            if (k == 1) { // single length palindrome
                table[i][j] = true
            } else if (k == 2) {
                if (str[i] == str[j]) table[i][j] = true
            } else { // for more than 3 length, w'll have middle elements
                if (table[i + 1][j - 1] && str[i] == str[j]) table[i][j] = true
            }
            // we found new bigger palindrome
            if (table[i][j] && k > max) {
                max = k
                start = i
            }
            // println("i$i, j=$j, k=$k table=${table[i][j]}, max=$max, start=$start")
        }
    }
    return str.substring(start, start + max)
};0

