 * @param end an integer representing the ending value for the range
 * @return a tuple containing the names of the farmers
 */
fun createFarmersCode(farmerCount: Int, start: Int, end: Int): List<String> {

    // Generate a range of values using the given start and end values
    val values = (start..end)

    // Initialize a list to store the farmer names
    val farmersList = mutableListOf<String>()

    // Iterate over the values
    for (value in values) {
        // Use the left shift operator to concatenate the farmer names with the list
        farmersList.add("Farmer $value")
    }

    // Add an additional farmer name using the right shift operator
    farmersList.add("Farmer ${end + 1}")

    return farmersList
}

