/**
 * Counts the number of valid photos taken by the photographer.
 *
 * @param photos A dictionary containing the details of each photo (filename, is_valid).
 * @return The count of valid photos.
 * @throws IllegalArgumentException If the 'is_valid' key in the photos dictionary is not a boolean.
 * @throws NoSuchElementException If the provided photos dictionary is empty.
 */
fun countPhotos(photos: Map<String, Boolean>): Int {

    try {
        if (photos.isEmpty()) {
            throw NoSuchElementException("No photos provided. Please provide a non-empty dictionary.")
        }

        var count = 0
        for ((filename, isValid) in photos) {
            if (isValid !is Boolean) {
                throw IllegalArgumentException("The value for 'is_valid' must be a boolean. Found '$isValid' for photo '$filename'.")
            }

            if (isValid) {
                count++
            }
        }

        return count
    } catch (e: NoSuchElementException) {
        println(e.message)
    } catch (e: IllegalArgumentException) {
        println(e.message)
    }

    return 0
}

