fun findIndexOf(s: String, text: String): Int {
    if (text.length < s.length) return -1

    val hash = RollingHash(s, s.length)
    var textHash = RollingHash(text, s.length)

    0.until(text.length - s.length + 1).forEach { i ->
        if (hash.value == textHash.value) return i
        textHash = textHash.roll()
    }

    return -1
};0

fun <T> stalinSort(source: Sequence<T>, descending: Boolean): List<T> where T : Comparable<T> {
    val iterator = source.iterator()
    val result = mutableListOf<T>()

    if (iterator.hasNext()) {
        var lastElement = iterator.next()
        result.add(lastElement)

        while (iterator.hasNext()) {
            val element = iterator.next()
            val compare = when (descending) {
                true -> element <= lastElement
                false -> lastElement <= element
            }
            if (compare) {
                result.add(element)
                lastElement = element
            }
        }
    }

    return result
};0

/**
