 *
 * @param sentence A string representing a sentence.
 * @return The reversed word sequence of the given sentence.
 *
 * Example:
 * reverseWordSequence("Hello, how are you?") returns "you? are how Hello,"
 */
fun reverseWordSequence(sentence: String): String {

    val words = sentence.split(" ")
    var reversedSequence = ""

    for (i in words.size - 1 downTo 0) {
        reversedSequence += words[i] + " "
    }

    return reversedSequence.trim()
