/**
 * Given a 3-dimensional array representing different layers of minerals in a geological formation,
 * this function determines the number of minerals that are present in the intersection of each layer.
 *
 * @param layers A 3-dimensional list where each element represents a layer and the nested elements
 * represent the minerals present in that layer.
 * @return The number of minerals that are present in the intersection of all layers.
 */
fun countMinerals(layers: List<List<List<String>>>) : Int {

    // Initialize a set to store the common minerals across all layers
    var commonMinerals = layers[0].toSet()

    // Iterate through the layers starting from the second layer
    for (layer in layers.subList(1, layers.size)) {
        // Find the intersection of current common minerals and the minerals of the current layer
        commonMinerals = commonMinerals.intersect(layer).toSet()
    }

    // Return the count of common minerals
    return commonMinerals.size
};1

/**
 * Find the adjacencies of a given number.
 * This is kind of horrible, but I'm not immediately sure of a better way.
 * We make sure i is a three digit number (by prepending 0s if required) and then rotate each digit both
 * positively and negatively to get the six adjacencies.
 */
fun calculateAdjacencies(i: Int): List<Int> {
    fun rotateDigitClockwise(str: String, i: Int): String {
        return str.take(max(0,i)) + when (str[i]) {
            '9' -> '0'
            else -> str[i] + 1
        } + str.drop(i+1)
    }

    fun rotateDigitCounterclockwise(str: String, i: Int): String = str.take(max(0,i)) + when (str[i]) {
        '0' -> '9'
        else -> str[i] - 1
    } + str.drop(i+1)

    val str = i.toString()
    val digits = (if (str.length < 3) "0".repeat(3 - str.length) else "") + str
    return (0 until 3).flatMap {
        idx -> listOf(rotateDigitClockwise(digits, idx), rotateDigitCounterclockwise(digits, idx))
    }.map { it.toInt() }
};0

fun tagUnions(repository: Repository) {
    val groupings = repository.groupsByTags.filter { it.value.size > 1 }
    val groups = groupings.values.map { it.map { it.name }.toHashSet() }.distinct().sortedByDescending { it.size }
    val allUnions = repository.groupUnions

    // initial pass
    groups.forEach { group ->
        val name = unionName(group)
        val superGroups = groups.filter { it !== group && it.containsAll(group) }
        val members = group.toList()
        val intersection = members.map { repository.tagGroups[it]!!.tags.toSet() }.reduce { a, b -> a.intersect(b) }

        val union = GroupUnion(members, intersection, emptyList(), emptyList(), superGroups.map(::unionName))
        require(union.name == name)

        allUnions[name] = union
    }

    // pass2: fill additionalTags and ambiguityTags
    groups.forEach { groupMembers ->
        val unionName = unionName(groupMembers)
        val union = allUnions[unionName]!!

        val additionalTags = union.intersectionTags.filter { tag -> union.superGroups.none { tag in allUnions[it]!!.intersectionTags } }
        val ambiguityTags = union.intersectionTags.filter { tag -> union.superGroups.count { tag in allUnions[it]!!.intersectionTags } > 1 }

        allUnions[unionName] = union.copy(additionalTags = additionalTags, ambiguityTags = ambiguityTags)
    }

    // transpose map
    val unionsByGroups = allUnions.values.flatMap { u -> u.members.map { it to u.name } }.groupBy({ it.first }, { allUnions[it.second]!! })
    repository.unionsByGroups = unionsByGroups
};0

fun getKnapSackItems(knapSack: List<MutableList<Int>>, weight: Int, items: List<List<Int>>): Pair<Int, List<Int>> {
    val sequence = mutableListOf<Int>()
    val pair = Pair(weight, sequence)
    var i = knapSack.size - 1
    var c = knapSack[0].size - 1
    while (i > 0) {
        if (knapSack[i][c] == knapSack[i-1][c]) {
            i--
        } else {
            sequence.add(i - 1)
            c -= items[i-1][1]
            i--
        }
        if (c == 0) {
            break
        }
    }
    return pair

};0

