fun hit(holes: Array<Int>, malletWidth: Int): Pair<Int, Int> {
    var max = -1
    var maxIndex = -1
    holes.toList().windowed(size = malletWidth, step = 1).forEachIndexed { i, window ->
        val sum = window.sum()
        if (sum > max) {
            max = sum
            maxIndex = i
        }
    }
    return Pair(maxIndex, max)
};0

fun collatzSequenceSize(n: Int): Int {
    val cached = cache[n]
    if (cached != null) {
        return cached
    }

    val next = if (n % 2 == 0) {
        collatzSequenceSize(n / 2) + 1
    } else {
        collatzSequenceSize((3 * n + 1) / 2) + 2
    }
    if (cache.size <= 1 shl 30) {
        cache[n] = next
    }

    return next
};0

fun solve(polymer: String, insertions: Map<String, Char>, steps: Int): Long {
  val memoizedGetDescendants = memoizeCountDescendantChars(insertions)

  val finalCount = sequence {
    // Count initial chars
    val initialCharCount = polymer
      .groupingBy { it }.eachCount()
      .mapValues { (_, v) -> v.toLong() }
      .toMutableMap()

    yield(initialCharCount)

    // Count descendant chars generated by each pair or chars ('abc' -> 'ab','bc')
    for (i in 0..(polymer.length - 2)) {
      val pair = polymer.substring(i, i + 2)
      yield(memoizedGetDescendants(pair, steps))
    }
  }.reduce(::combine2)

  val max = finalCount.maxOf { it.value }
  val min = finalCount.minOf { it.value }
  return max - min
};0

