/**
 * You are a fashion designer working on multiple clothing collections. Each collection is represented as a set of
 * colors. Your task is to find the common colors that are present in all the collections.
 *
 * Complete the 'findCommonColors' function to find the intersection of all the sets in the 'collections' list and
 * return a set of common colors.
 *
 * Example:
 * collections = [{
'red', 'blue', 'green'}, {'blue', 'yellow'}, {'red', 'green', 'purple', 'black'}, {'blue', 'pink'}]
 * findCommonColors(collections) should return {'blue'}
 *
 * @param collections A list of sets representing the colors of each clothing collection.
 * @return A set containing the colors that are common in all the collections.
 *
 * NOTE: The input list can have any number of sets and each set can contain any number of colors (at least 1).
 */
fun findCommonColors(collections: List<Set<String>>): Set<String> {
    if (collections.isEmpty()) {
        return emptySet()
    }

    var commonColors = HashSet(collections[0])
    for (collection in collections.subList(1, collections.size)) {
        commonColors = commonColors.intersect(collection).toHashSet()
    }

    return commonColors
};1

fun highAndLow2(numbers: String): String {
    val firstNumber: Int = numbers.split(" ").get(0).toIntOrNull() ?: -1
    val result = numbers.split(" ").fold(Pair</*max*/Int,/*min*/Int>(firstNumber, firstNumber)) { acc, it ->
        val item = it.toIntOrNull() ?: -1
        return@fold when {
            item > acc.first -> acc.copy(first = item)
            item < acc.second -> acc.copy(second = item)
            else -> acc
        }
    }
    return "${result.first} ${result.second}"
};0

fun dist(x1: Long, y1: Long, x2: Long, y2: Long) = Math.abs(x1 - x2) + Math.abs(y1 - y2)

