        .map { Regex("-?\\d+").findAll(it).toList() }
        .map { it.map { it.value.toLong() } }
        .sortedBy() { it[0] }
    val y = 2_000_000L
    (-1_000_000L..6_000_000L).count { x ->
        sensors
            .filter { it[2] != x || it[3] != y }
            .any { (xs, ys, xb, yb) -> dist(xs, ys, x, y) <= dist(xs, ys, xb, yb) }
