    for (y in 0L..4_000_000L) {
        var x = 0L
        for ((xs, ys, xb, yb) in sensors)
            if (dist(xs, ys, x, y) <= dist(xs, ys, xb, yb))
                x = xs + dist(xs, ys, xb, yb) - Math.abs(ys - y) + 1
        if (x <= 4_000_000L)
            println(x * 4_000_000L + y)
    }
};0

fun highlyDivisibleTriangularNumber(n: Int): Int {
    var num = 1
    while (true) {
        val triangular = (num * (num + 1)) / 2
        val numberOfFactors = primeFactorizationOf(triangular)
            .map { it.value + 1 }
            .fold(1L) { acc, i -> acc * i }

        if (numberOfFactors > n) {
            return triangular
        }

        num++
    }
};0

