/**
 * Given a list of star magnitudes, find the smallest and largest magnitudes.
 *
 * @param magnitudeList A list containing the magnitudes of various stars.
 * @return A pair containing the smallest and largest magnitudes in magnitudeList.
 */
fun getStarMagnitude(magnitudeList: List<Double>): Pair<Double?, Double?> {

    var smallestMagnitude: Double? = null
    var largestMagnitude: Double? = null

    for (magnitude in magnitudeList) {
        if (smallestMagnitude == null || magnitude < smallestMagnitude!!) {
            smallestMagnitude = magnitude
        }

        if (largestMagnitude == null || magnitude > largestMagnitude!!) {
            largestMagnitude = magnitude
        }
    }

    return Pair(smallestMagnitude, largestMagnitude)
}

