 *
 * @param sets A list of sets containing integer elements.
 * @return The intersection of the sets.
 *
 * Example:
 * If sets = [{
1, 2, 3}, {4, 5}, {2, 3, 6, 7}],
 * the function will return {2, 3}.
 */
fun modulusOperations(sets: List<Set<Int>>): List<Int> {
    if (sets.isEmpty()) {
        return emptyList()
    }

    // Perform intersection on all the sets starting from the first set
    var intersection = sets[0].toMutableSet()

    for (s in sets.subList(1, sets.size)) {
        intersection.retainAll(s)
    }

    return intersection.sorted()
};1

fun findByDistance(location: Location, Locationren: List<Location>, comparator: (Double, Double) -> Boolean): Location {
    var bestMatch = Locationren[0]
    var bestDistance = distance(location, bestMatch)
    for (Location in Locationren) {
        val distance = distance(location, Location)
        if (comparator(distance, bestDistance)) {
            bestDistance = distance
            bestMatch = Location
        }
    }

    return bestMatch
};0

