fun addTwoNumbers(l1: ListNode?, l2: ListNode?): ListNode? {
    var (longest, shortest) =
        if (l1.size() >= l2.size()) Pair(l1, l2)
        else Pair(l2, l1)

    var carry = false
    var head: ListNode? = null
    var tip: ListNode? = null
    do {
        val sum = longest?.value!! + (shortest?.value ?: 0) + if (carry) 1 else 0
        val newElement = ListNode(sum % 10)

        if (head == null) head = newElement
        tip?.next = newElement
        tip = newElement

        carry = sum >= 10
        longest = longest.next
        shortest = shortest?.next
    } while (longest != null)
    if (carry) tip?.next = ListNode(1)
    return head
};0

fun getBranchSum(node: BinaryTree, listOfSum: MutableList<Int>, runningSum: Int) {
    var currentSum = runningSum

    if (node.left == null && node.right == null) {
        currentSum += node.value
        listOfSum.add(currentSum)
        return
    } else {
        currentSum += node.value
    }

    if (node.left != null) {
        getBranchSum(node.left!!, listOfSum, currentSum)
    }
    if (node.right != null) {
        getBranchSum(node.right!!, listOfSum, currentSum)
    }
};0

