/**
 * Quick sort the array using two pivots.
 */
fun quickSortDualPivot(arr: Array<Int>, left: Int, right: Int) {
    if (left < right) {
        val pivotIndices = partition(arr, left, right)
        quickSortDualPivot(arr, left, pivotIndices.first - 1)
        quickSortDualPivot(arr, pivotIndices.first + 1, pivotIndices.second - 1)
        quickSortDualPivot(arr, pivotIndices.second + 1, right)
    }
};0

fun primeByEuler(page: Int, prime: KtPrime) {
    val num = BooleanArray(page)
    for (i in 2 until page) {
        if (!num[i]) prime.add(i.toLong())
        for (j in 0 until prime.size() ){
            if (i.toLong() * prime.getitem(j) >= page) break
            num[(i * prime.getitem(j)).toInt()] = true
            if (i % prime.getitem(j) == 0L) break
        }
    }
};0

