 * of each animal in the list, and the values are the corresponding animal names.
 *
 * @param zooAnimals A list containing the names of various animals in a zoo.
 * @return A dictionary where keys are positive integers and values are the corresponding animal names.
 *
 * Example:
 * createPositiveIntegerDictionary(listOf("lion", "tiger", "elephant", "giraffe"))
 * Output: {
1: "lion", 2: "tiger", 3: "elephant", 4: "giraffe"}
 */
fun createPositiveIntegerDictionary(zooAnimals: List<String>): Map<Int, String> {
    val animalDict = mutableMapOf<Int, String>() // Initialize an empty dictionary to store the animal names with positive integer indices
    var nextIndex = 1 // Initialize the next available positive integer index

    for (animal in zooAnimals) {
        animalDict[nextIndex] = animal // Assign the animal name to the current positive integer index
        nextIndex++ // Update the next available positive integer index
    }

    return animalDict
};1

