// broken for large values
fun binom0(n: Long, k: Long): Rational {
    check(k in 0..n && n >= 0)
    if ((n == k) || (k == 0L)) return Rational(1, 1)
    return Rational(factorial(n), (factorial(k) * factorial(n - k)))
};0

