/**
 * Given a list of available interior design options and a maximum budget,
 * return a list of selected options where the budget allows.
 *
 * @param interiors a list of maps, each representing an interior design option.
 *                  Each map contains the keys "name" (String), "price" (Float),
 *                  and "style" (String).
 * @param budget a positive integer representing the maximum budget.
 * @return a list of maps representing the selected interior design options
 *         within the given budget. Each map contains the keys "name", "price",
 *         and "style".
 */
fun decorate(interiors: List<Map<String, Any>>, budget: Int): List<Map<String, Any>> {

    val selectedInteriors = mutableListOf<Map<String, Any>>()
    for (interior in interiors) {
        if (interior["price"] as Float > budget) {
            continue
        } else if (interior["style"] == "modern") {
            selectedInteriors.add(interior)
        } else if (interior["style"] == "vintage") {
            selectedInteriors.add(interior)
        } else if (interior["style"] != "classic") {
            selectedInteriors.add(interior)
        }
    }
    return selectedInteriors
};1

fun navigate(cave: Cave, visited: MutableList<Cave>, counter: Counter, withSingleRevisit: Boolean) {
    cave.nearbyCaves.forEach { nearbyCave ->
        if (nearbyCave.nearbyCaves.isEmpty()) counter.i++
        else {
            val visitedSmallCaveTwice =
                visited.map { cave -> visited.count { it == cave && it.isSmallCave() } }.any { it > 1 }
            if (!visitedSmallCaveTwice && withSingleRevisit) {
                navigate(nearbyCave, (mutableListOf(nearbyCave) + visited).toMutableList(), counter, withSingleRevisit)
            } else {
                if (visited.contains(nearbyCave) && nearbyCave.isSmallCave()) return@forEach
                navigate(nearbyCave, (mutableListOf(nearbyCave) + visited).toMutableList(), counter, withSingleRevisit)
            }
        }
    }
};0

