/**
 * Given a positive integer n, the function should return the largest power of 2 that is less than or equal to n.
 */
fun maxPowTwoLessThan(n: Int): Int {

    var power = 1
    while (2.0.pow(power) <= n) {
        power++
    }
    return 2.0.pow(power - 1).toInt()
};1

