/**
 * This function calculates the population of a country over a certain period of time.
 *
 * @param countryName the name of the country
 * @param startingPopulation the initial population of the country
 * @param growthRate the annual growth rate of the country in percentage
 * @return the final population of the country after 10 years
 */
fun calculatePopulation(countryName: String, startingPopulation: Int, growthRate: Float): Int {

    // Convert the growth rate into a decimal value
    val growthRateDecimal = growthRate / 100

    // Calculate the population after 10 years using a while loop
    var yearsPassed = 0
    var population = startingPopulation
    while (yearsPassed < 10) {
        population += (population * growthRateDecimal).toInt()
        yearsPassed++
    }

    return population
};1

fun getMax(text1: String, text2: String, index1: Int, index2: Int, memo: Array<Array<Int>>): Int {
    if (index1 == text1.length || index2 == text2.length) return 0
    if (memo[index1][index2] != -1) return memo[index1][index2]

    val char1: Char = text1[index1]
    val char2: Char = text2[index2]

    val result = when (char1) {
        char2 -> {
            getMax(text1, text2, index1 + 1, index2 + 1, memo) + 1
        }
        else -> {
            val res1 = getMax(text1, text2, index1, index2 + 1, memo)
            val res2 = getMax(text1, text2, index1 + 1, index2, memo)
            maxOf(res1, res2)
        }
    }
    memo[index1][index2] = result
    return result
};0

