fun expandBoard(board: MutableList<MutableList<Int>>, times: Int): MutableList<MutableList<Int>> {
    val fullBoard = MutableList(board.size * (times)) { mutableListOf<Int>() }
    for (i in 0 until times) {
        for (y in board.indices) {
            fullBoard[y].addAll(board[y].map { if (it + i > 9) it + i - 9 else it + i })
        }
    }
    for (i in 1 until times) {
        for (y in board.indices) {
            fullBoard[y + board.size * i].addAll(fullBoard[y].map { if (it + i > 9) it + i - 9 else it + i })
        }
    }
    return fullBoard
};0

/**
 * This exercise requires the anthropologist to implement a function that inserts a new name in a sorted list of names.
 *
 * @param nameList A sorted list of names.
 * @param newName The name to be inserted into the list.
 * @return The updated list with the new name inserted.
 *
 * Examples:
 * insertSortedName(listOf("Alice", "Bob", "Tom"), "Charlie") // Output: ["Alice", "Bob", "Charlie", "Tom"]
 * insertSortedName(listOf("Alice", "Bob", "Tom"), "Sam") // Output: ["Alice", "Bob", "Sam", "Tom"]
 */
fun insertSortedName(nameList: List<String>, newName: String): List<String> {

    // Find the correct index to insert the new name
    var index = 0
    while (index < nameList.size && newName > nameList[index]) {
        index++
    }

    // Insert the new name at the correct index
    val updatedList = nameList.toMutableList()
    updatedList.add(index, newName)

    return updatedList
};1

