fun List<String>.foldDownBySignificance(byLeast: Boolean = false) = (0 until this[0].length).fold(this) { acc: List<String>, index: Int ->
    if (acc.size == 1) return@fold acc
    val oneCount = acc.map { it[index] }.count { char -> char == '1' }
    val zeroCount = acc.map { it[index] }.count { char -> char == '0' }

    val significanceBit = if (byLeast) {
        if (oneCount < zeroCount) '1' else '0'
    } else {
        if (oneCount >= zeroCount) '1' else '0'
    }

    acc.filter { it[index] == significanceBit }
}.first();0

/**
 * Given a nested list representing a grid of geographic temperature data,
 * write a function that finds the lowest temperature.
 *
 * @param geographicData A nested list representing temperature data.
 * @return The lowest temperature found in the dataset.
 */
fun findLowestTemperature(geographicData: List<List<Float>>): Float {

    var lowestTemperature: Float? = null

    for (row in geographicData) {
        for (temperature in row) {
            if (lowestTemperature == null || temperature < lowestTemperature!!) {
                lowestTemperature = temperature
            }
        }
    }

    return lowestTemperature ?: 0.0f
}

