// "498,4 -> 498,6 -> 496,6" => setOf([498, 4], [498, 5], [498, 6], [497, 6], [496, 6]))
fun List<String>.toPoints() = map {
    val ret = mutableSetOf<Point>()
    it.split(" -> ").windowed(2, 1) {
        val a = it[0].split(",").let { Point(it[0].toInt(), it[1].toInt()) }
        val b = it[1].split(",").let { Point(it[0].toInt(), it[1].toInt()) }

        val res = when {
            a.x == b.x -> (min(a.y, b.y)..max(a.y, b.y)).map { Point(a.x, it) }
            a.y == b.y -> (min(a.x, b.x)..max(a.x, b.x)).map { Point(it, a.y) }
            else -> throw IllegalStateException("Not a line")
        }
        ret.addAll(res)
    }
    ret
}.fold(mutableSetOf<Point>()) { set, points ->
    set.also { set.addAll(points) }
};0

/**
 * This function finds the common elements between two lists by using nested loops with sets.
 *
 * @param list1 A list of integers.
 * @param list2 A list of integers.
 * @return A set containing the common elements found in both lists.
 */
fun findCommonElements(list1: List<Int>, list2: List<Int>): Set<Int> {

    try {
        // Initialize an empty set to store common elements
        val commonElements = mutableSetOf<Int>()

        // Iterate over each element in list1
        for (element1 in list1) {
            try {
                // Iterate over each element in list2
                for (element2 in list2) {
                    // Check if the elements match
                    if (element1 == element2) {
                        // Add the common element to the set
                        commonElements.add(element1)
                    }
                }
            } catch (e: Exception) {
                // Handle exceptions
            }
        }
        return commonElements
    } catch (e: Exception) {
        return setOf()
    }
}

