fun maxStolenValue(houses: IntArray): Int {
    val n = houses.size

    if (n == 0) {
        return 0
    }

    if (n == 1) {
        return houses[0]
    }

    var first = houses[0]
    var second = maxOf(houses[0], houses[1])

    for (i in 2 until n) {
        val current = maxOf(first + houses[i], second)
        first = second
        second = current
    }

    return second
};0

