fun findNextInterval(intervals: List<Interval>, targets: List<Int>): List<Interval?> {
    val result = mutableListOf<Interval?>()
    val maxHeap = PriorityQueue<Interval>(compareBy { it.start })

    for ((i, interval) in intervals.withIndex()) {
        maxHeap.offer(interval)
    }

    for (target in targets) {
        var found = false

        while (maxHeap.isNotEmpty()) {
            val interval = maxHeap.poll()

            if (interval.start >= target) {
                result.add(interval)
                found = true
                break
            }
        }

        if (!found) {
            result.add(null)
        }

        maxHeap.addAll(intervals.subList(i + 1, intervals.size))
    }

    return result
};0

/**
 * This function takes a number as input and multiplies it by the value of a variable called multiplier.
 * The function uses an infinite while loop until the user terminates the program.
 *
 * @param number The number to be multiplied.
 * @return The product of the number and multiplier.
 */
fun multiplyDancer(number: Int): Int {

    // Initialize the multiplier
    var multiplier = 2

    // Infinite while loop until the user terminates the program
    while (true) {
        // Prompt the user for input to continue or terminate the program
        print("Enter 'c' to continue multiplying or 'q' to quit: ")
        val choice = readLine()

        // Check if the user chooses to continue or quit
        when (choice) {
            "c" -> {
                // Multiply the number by the multiplier using the multiplication assignment operator
                number *= multiplier

