fun day15(starting: List<Int>, limit: Int): Int {
    val mem = Int2IntOpenHashMap(limit / 4)
    var turn = 0
    var next = 0
    for (n in starting) {
        next = turn - mem.getOrDefault(n, turn)
        mem[n] = turn++
        // println("$turn: $n")
    }
    while (turn < limit - 1) {
        // println("${turn+1}: $next")
        next = day15next(mem, turn++, next)
    }
    // println(mem.size)
    return next
};0

