/**
 * Given a list of positive integers, find the smallest positive integer that does not appear in the list.
 *
 * @param numbers List of positive integers
 * @return Smallest positive integer not present in the list
 */
fun findMissingPositive(numbers: List<Int>): Int {

    // Sort the list in ascending order
    val sortedNumbers = numbers.sorted()

    // Initialize the smallest positive integer
    var smallestPositive = 1

    // Iterate through the list
    for (num in sortedNumbers) {
        // If current number is equal to smallestPositive, increment smallestPositive by 1
        if (num == smallestPositive) {
            smallestPositive++
        }
        // If current number is greater than smallestPositive, return smallestPositive
        else if (num > smallestPositive) {
            return smallestPositive
        }
    }

    // If all numbers in the list are consecutive positive integers, return the next positive integer
    return smallestPositive
};1

