 */
fun complexPower(complexNumber: Complex, exponent: Int): Complex {

    var result = Complex(1.0, 0.0)
    for (i in 0 until Math.abs(exponent)) {
        result *= complexNumber
    }
    if (exponent < 0) {
        result = Complex(1.0, 0.0) / result
    }
    return result
