 *
 * @param numbers A list of numbers (Float or Int)
 * @return A list with modified elements, where the smallest square number is replaced with its square root.
 */
fun findSmallestSquare(numbers: List<Number>): List<Number> {

    val squares = mutableListOf<Number>()
    for (number in numbers) {
        if (number == (Math.sqrt(number.toDouble()).toInt()).toDouble().pow(2.0)) {  // Check if the number is a perfect square
            squares.add(Math.sqrt(number.toDouble()))  // Append the square root of the square number
