operator fun MyDate.rangeTo(other: MyDate): DateRange = DateRange(this, other)

class DateRange(val start: MyDate, val endInclusive: MyDate) {
    operator fun contains(d: MyDate) = start <= d && d <= endInclusive
    operator fun iterator(): Iterator<MyDate> {
        return object : Iterator<MyDate> {
            var currentDate = start.copy()
            fun hasNext(): Boolean {
                return currentDate <= endInclusive
            }

            fun next(): MyDate {
                val retDate = currentDate
                currentDate = currentDate.nextDay()
                return retDate
            }
        }
    }
};0

fun optimise(meetings: Set<Meeting>, hours: Int): Set<Meeting> {
    val sorted = meetings.sortedBy { it.hours }.toMutableList()
    var hoursLeft = hours
    val result = LinkedHashSet<Meeting>()
    while (sorted.isNotEmpty()) {
        val meeting = sorted.removeAt(0)
        hoursLeft -= meeting.hours
        if (hoursLeft < 0) break
        result.add(meeting)
    }
    return result
