fun fourSum(nums: IntArray, target: Int): List<List<Int>> {
    val result = arrayListOf<ArrayList<Int>>()
    if (nums.size < 4) {
        return result
    }
    nums.sort()
    var index = 0
    while (index < nums.size) {
        if (index > 0 && nums[index] == nums[index - 1]) {
        } else {
            val tempNums = nums.filterIndexed { i, v -> i > index }.toIntArray()
            val tResult = threeSum(tempNums, target - nums[index])
            tResult.forEach {
                val l = it as ArrayList
                l.add(nums[index])
                result.add(l)
            }
        }
        index += 1
    }
    return result
};0

fun longestString(s: String): String {
    val s1 = s.takeWhile { it.isVowel() }
    val s3 = s.takeLastWhile { it.isVowel() }
    val s2 = s.drop(s1.length).dropLast(s3.length).let { s2 ->
        var from = 0
        var max = ""
        s2.forEachIndexed { i, char ->
            if (!char.isVowel()) {
                if (i - from > max.length) max = s2.substring(from, i)
                from = i + 1
            }
        }
        max
    }
    return s1 + s2 + s3
};0

