fun climbingLeaderboard(scores: IntArray, player: IntArray): IntArray? {
    val scoreSize = scores.size
    val playerScoresSize = player.size
    val ranking = IntArray(playerScoresSize)
    val rank = IntArray(scoreSize)
    rank[0] = 1
    for (i in 1 until scoreSize) {
        if (scores[i] == scores[i - 1]) {
            rank[i] = rank[i - 1]
        } else {
            rank[i] = rank[i - 1] + 1
        }
    }
    for (i in 0 until playerScoresSize) {
        val aliceScore = player[i]
        if (aliceScore > scores[0]) {
            ranking[i] = 1
        } else if (aliceScore < scores[scoreSize - 1]) {
            ranking[i] = rank[scoreSize - 1] + 1
        } else {
            val index = binarySearch(scores, aliceScore)
            ranking[i] = rank[index]
        }
    }
    return ranking
};0

fun playRockPaperScissorRound(opponent: Symbol, me: Symbol): Int {
    // Opponent wins
    if ((opponent == Symbol.ROCK && me == Symbol.SCISSOR)
        || (opponent == Symbol.PAPER && me == Symbol.ROCK)
        || (opponent == Symbol.SCISSOR && me == Symbol.PAPER)
    ) {
        return me.ordinal + 1
    }

    // Me wins
    if ((me == Symbol.ROCK && opponent == Symbol.SCISSOR)
        || (me == Symbol.PAPER && opponent == Symbol.ROCK)
        || (me == Symbol.SCISSOR && opponent == Symbol.PAPER)
    ) {
        return 6 + me.ordinal + 1
    }

    // Draw
    return 3 + me.ordinal + 1
};0

/**
 * Given a list of numbers, find and return a list of all the numbers that appear more than once.
 */
fun findDuplicates(numbers: List<Int>): List<Int> {

    val duplicates = mutableListOf<Int>()
    for (i in numbers.indices) {
        for (j in i + 1 until numbers.size) {
            if (numbers[i] == numbers[j] && numbers[i] !in duplicates) {
                duplicates.add(numbers[i])
            }
        }
    }
    return duplicates
};1

/**
 * This function performs the specified action on two marketing lists using sets.
 *
 * @param marketingList1 The first marketing list.
 * @param marketingList2 The second marketing list.
 * @param action The action to be performed on the lists. 'intersection' to find the common elements,
 *               'append' to combine the lists, or 'remove' to remove common elements.
 * @return The result of the specified action on the marketing lists.
 * @throws IllegalArgumentException If the action parameter is not 'intersection', 'append', or 'remove'.
 */
fun setOperation(marketingList1: Set<String>, marketingList2: Set<String>, action: String): Set<String> {

