fun dagShortestPath(graph: MutableMap<Int, MutableList<Edge>>, start: Int, numNodes: Int): Array<Int> {
    val topSort = topologicalSort(graph, numNodes)
    val distance = Array<Int>(numNodes) { -1 }

    distance[start] = 0

    for (i in 0 until numNodes) {
        val nodeIdx = topSort[i]
        if (distance[nodeIdx] != -1) {
            val adjacencyList = graph[nodeIdx]
            if (adjacencyList != null) {
                for (edge in adjacencyList) {
                    val newDest = distance[nodeIdx] + edge.weight
                    if (distance[edge.dst] == null) distance[edge.dst] = newDest
                    else distance[edge.dst] = kotlin.math.min(distance[edge.dst], newDest)
                }
            }
        }
    }

    return distance
};0

/**
 * Given a list of numbers, calculate the quotient of each pair of adjacent numbers using the division assignment operator (/=).
 * However, if a pair of numbers is divisible by 13, immediately break out of the loop and return -1.
 *
 * @param numbers A list of numbers.
 * @return The quotient of each pair of adjacent numbers, or -1 if a pair of numbers is divisible by 13.
 */
fun calculateDivisionAssignment(numbers: List<Int>): Int {

    var quotient = 1
    for (i in 1 until numbers.size) {
        quotient /= numbers[i - 1]
        if (numbers[i - 1] % 13 == 0) {
            break
        }
    }
    return quotient
};1

