/**
 * A method for a musician to play a song with specific timing and rhythm.
 *
 * @param songLength The total length of the song in seconds.
 * @param rhythm A list of pairs, each containing two elements representing note duration and note value.
 * @return The output string indicating the song being played.
 */
fun playSong(songLength: Int, rhythm: List<Pair<Int, String>>): String {

    var totalDuration = 0  // The accumulated duration of notes played
    var songOutput = ""  // The output string indicating the song being played

    for ((duration, value) in rhythm) {
        totalDuration += duration

        if ((totalDuration % 5 == 0) && (duration % 2 != 0)) {  // Short-circuiting and modulus intersection
            songOutput += value.toUpperCase()
        } else if ((duration % 3 != 0) || (totalDuration % 7 == 0)) {  // Short-circuiting and modulus intersection
            songOutput += value.toLowerCase()
        } else {
            songOutput += value
        }

        if (totalDuration >= songLength) {
            break
        }
    }

    return songOutput
}

