/**
 * Helper function to compare two floating-point values within epsilon.
 *
 * @param a First value to compare.
 * @param b Second value to compare.
 * @param epsilon The threshold for considering floating-point error.
 * @return True if the values are considered equal, False otherwise.
 */
fun fuzzyCompare(a: Double, b: Double, epsilon: Double): Boolean {

    return Math.abs(a - b) < epsilon
}

fun fuzzySetIntersection(sets: List<Set<Double>>, epsilon: Double): Set<Double> {
    if (sets.isEmpty()) {
        return emptySet()
    }

    var result = HashSet(sets[0])
    for (s in sets.subList(1, sets.size)) {
        result = result.filter { val -> s.any { elem -> fuzzyCompare(val, elem, epsilon) }.toSet()
    }

    return result
}

