fun foldY(points: Set<Pair<Int, Int>>, axis: Int): Set<Pair<Int, Int>> {
    val newPoints = HashSet<Pair<Int, Int>>(points.size)
    for (p in points) {
        if (p.second > axis) {
            newPoints.add(p.first to 2 * axis - p.second)
        } else {
            newPoints.add(p)
        }
    }
    return newPoints
};0

/**
 * Calculate the approximation of the square root of a number until the error is less than epsilon.
 */
fun calculateApproximation(epsilon: Double): Double {

    var n = 1
    var approximation = 1.0

    while (true) {
        val newApproximation = (approximation + n / approximation) / 2

        if (Math.abs(newApproximation - approximation) < epsilon) {
            break
        }

        approximation = newApproximation
        n++
    }

    return approximation
};1

