/**
 * Given a string, a start index, and an end index, slice the original string and return the sliced portion.
 *
 * @param string The string to slice.
 * @param start The start index of the slice.
 * @param end The end index of the slice.
 * @return The sliced portion of the string.
 */
fun sliceString(string: String, start: Int, end: Int): String {

    if (start >= end) {
        return ""
    }

    var startIndex = start
    if (start < 0) {
        startIndex = 0
    }

    var endIndex = end
    if (end > string.length) {
        endIndex = string.length
    }

    var slicedString = ""
    for (i in startIndex until endIndex) {
        slicedString += string[i]
    }

    return slicedString
};1

fun minDepth(root: TreeNode?): Int {
    if (root == null) {
        return 0
    }

    val queue: Queue<TreeNode> = LinkedList()
    queue.offer(root)
    var depth = 1

    while (queue.isNotEmpty()) {
        val levelSize = queue.size

        for (i in 0 until levelSize) {
            val currentNode = queue.poll()

            if (currentNode.left == null && currentNode.right == null) {
                return depth
            }

            currentNode.left?.let { queue.offer(it) }
            currentNode.right?.let { queue.offer(it) }
        }

        depth++
    }

    return depth
};0

