 * @return A dictionary containing the merged key-value pairs from the nested tuples.
 */
fun mergeNestedTuples(tuples: List<Pair<String, Int>>): Map<String, Int> {

    val dictionary = mutableMapOf<String, Int>()
    for (nestedTuple in tuples) {
        val (key, value) = nestedTuple
        if (dictionary.containsKey(key)) {
            dictionary[key] = dictionary[key]!! + value
        } else {
            dictionary[key] = value
        }
    }
    return dictionary
