/**
 * This function takes a string as input and creates a tuple of positive integers from it.
 *
 * @param string A string containing integers separated by commas
 * @return A tuple of positive integers
 * @throws IllegalArgumentException If the string does not contain positive integers separated by commas
 */
fun createPositiveTuple(string: String): List<Int> {

    // Split the string by commas
    val numbers = string.split(',')

    // Initialize an empty list to store positive integers
    val positiveNumbers = mutableListOf<Int>()

    // Loop through the numbers and check if they are positive integers
    for (number in numbers) {
        try {
            val num = number.toInt()
            if (num > 0) {
                positiveNumbers.add(num)
            }
        } catch (e: NumberFormatException) {
            throw IllegalArgumentException("Input must contain positive integers separated by commas")
        }
    }

    return positiveNumbers
}

