 *
 * @param start The starting point of the range.
 * @param end The ending point of the range.
 * @return The count of odd numbers within the specified range.
 *
 * Example:
 * countOddNumbers(1, 10) -> 5
 * countOddNumbers(-5, 5) -> 6
 * countOddNumbers(0, 20) -> 11
 */
fun countOddNumbers(start: Int, end: Int): Int {

    var count = 0

    for (num in start..end) {
        if (num % 2 != 0) {
            count++
        }
    }

    return count
