fun borrowBook(library: List<List<String>>, bookTitle: String, memberType: String): String {

    if (searchBooks(library, bookTitle)) {
        for (shelf in library) {
            for (book in shelf) {
                if (book == bookTitle) {
                    when (memberType) {
                        "student" -> {
                            if ("Available for students" in book) {
                                return "Book available"
                            } else {
                                return "Book unavailable"
                            }
                        }
                        "teacher" -> {
                            if ("Available for teachers" in book) {
                                return "Book available"
                            } else {
                                return "Book unavailable"
                            }
                        }
                        "librarian" -> {
                            if ("Available for librarians" in book) {
                                return "Book available"
                            } else {
                                return "Book unavailable"
                            }
                        }
                    }
                }
            }
        }
    }
    return "Book unavailable"
