fun List<Position>.getNumberOfSides(): Int {
    val maxX = maxOf { it.x }
    val maxY = maxOf { it.y }
    val maxZ = maxOf { it.z }

    val sideX = (0..maxY).map { (0..maxZ).map { 0 }.toMutableList() }
    val sideY = (0..maxZ).map { (0..maxX).map { 0 }.toMutableList() }
    val sideZ = (0..maxX).map { (0..maxY).map { 0 }.toMutableList() }

    for (cube in this) {
        sideX[cube.y][cube.z] = sideX[cube.y][cube.z] xor (1 shl cube.x)
        sideX[cube.y][cube.z] = sideX[cube.y][cube.z] xor (1 shl cube.x + 1)

        sideY[cube.z][cube.x] = sideY[cube.z][cube.x] xor (1 shl cube.y)
        sideY[cube.z][cube.x] = sideY[cube.z][cube.x] xor (1 shl cube.y + 1)

        sideZ[cube.x][cube.y] = sideZ[cube.x][cube.y] xor (1 shl cube.z)
        sideZ[cube.x][cube.y] = sideZ[cube.x][cube.y] xor (1 shl cube.z + 1)
    }

    val numOfSidesX = sideX.sumOf { it.sumOf { Integer.bitCount(it) } }
    val numOfSidesY = sideY.sumOf { it.sumOf { Integer.bitCount(it) } }
    val numOfSidesZ = sideZ.sumOf { it.sumOf { Integer.bitCount(it) } }
    return numOfSidesX + numOfSidesY + numOfSidesZ
};0

/**
 * This function calculates the average speed of a police officer when given the distance covered and the time taken.
 *
 * @param distance The distance covered by the police officer in kilometers.
 * @param time The time taken by the police officer to cover the distance in hours.
 * @return The average speed of the police officer in kilometers per hour.
 */
fun calculateAverageSpeed(distance: Double, time: Double): Double {

    // Calculate the average speed
    val averageSpeed = distance / time

    // Retrieve the decimal part of the average speed
    val decimalPart = averageSpeed - averageSpeed.toInt()

    // Multiply the decimal part of the average speed with the digit at position 1
    val result = decimalPart * averageSpeed.toString()[2].toString().toDouble()

    return result
}

