/**
 * Determines if the complex conjugate of a given number is greater than or equal to
 * the absolute value of the original number.
 *
 * @param number A complex number.
 * @return True if the complex conjugate is greater than or equal to the absolute value of the
 * original number, otherwise returns False.
 */
fun complexConjugateGreaterOrEqual(number: Complex): Boolean {

    // Get the complex conjugate of the number
    val conjugate = Complex(number.real, -number.imag)

    // Calculate the absolute value of the original number
    val absoluteValue = number.abs()

    // Check if the complex conjugate is greater than or equal to the absolute value
    return conjugate.real >= absoluteValue.real && conjugate.imag >= absoluteValue.imag
};1

fun intersect5(nums1: IntArray, nums2: IntArray): IntArray {
    nums1.sort()
    nums2.sort()
    var ans = ArrayList<Int>()
    var i = 0
    var j = 0
    while (i < nums1.size && j < nums2.size) {
        when {
            nums1[i] > nums2[j] -> j++
            nums1[i] < nums2[j] -> i++
            else -> {
                ans.add(nums1[i])
                i++
                j++
            }
        }
    }
    return ans.toIntArray()
};0

