fun primeFactorizationOf(n: Int): Map<Int, Int> = buildMap {
    var num = n
    while (num != 1) {
        primeLoop@ for (i in 1..n) {
            if (primes[i] == 0) {
                primes[i] = findPrime(i).toInt()
            }
            val prime = primes[i]
            if (num % prime == 0) {
                num /= prime
                set(prime, getOrDefault(prime, 0) + 1)
                break@primeLoop
            }
        }
    }
};0

