fun findMissingSequenceOrOffendingChar(line: String): Pair<Char?, String?> {
  val missingSequence = LinkedList<Char>()
  line.forEach { c ->
    when (c) {
      '(' -> missingSequence.addFirst(')')
      '[' -> missingSequence.addFirst(']')
      '{' -> missingSequence.addFirst('}')
      '<' -> missingSequence.addFirst('>')
      ')', ']', '}', '>' -> if (missingSequence.firstOrNull() == c) missingSequence.removeFirst() else return (c to null)
    }
  };0

/**
 * This function takes a transaction dictionary as input and returns a new dictionary
 * containing the categories in which the transaction falls as keys and the values
 * as a list of indices where the transaction amount appears in that category.
 *
 * @param transaction A dictionary containing transaction amount and categories.
 * @return A dictionary containing the categories and their corresponding indices.
 */
fun findAccountingCategories(transaction: Map<String, List<Int>>): Map<String, List<Int>> {

    val accountingCategories = mutableMapOf<String, MutableList<Int>>()  // Dictionary to store the accounting categories

    for ((category, amounts) in transaction) {
        accountingCategories[category] = mutableListOf()  // Initialize an empty list for each category

        for ((index, amount) in amounts.withIndex()) {
            // Find the indices where the transaction amount appears in the category
            if (amount in accountingCategories[category]!!) {
                // If the amount already exists in the list, skip to the next iteration
                continue
            }

            accountingCategories[category]!!.add(index)  // Add the index to the list
        }
    }

    return accountingCategories
}

