/**
 * Given a string, perform the following tasks:
 * - Slice the string to obtain the substring from the 2nd character till the 7th character.
 * - Create a tuple of numbers from 1 to 10, but exclude the numbers from 4 to 8 (inclusive).
 * - Return the concatenation of the sliced substring and the created tuple as a single string.
 *
 * Example:
 * mathematicianShenanigans("HelloWorld") should return "lloWo(1, 2, 3, 9, 10)".
 */
fun mathematicianShenanigans(string: String): String {

    // Slicing the string to get the substring
    val slicedSubstring = string.substring(1, 7)

    // Creating the tuple by excluding numbers from 4 to 8
    val numTuple = (1..10).filter { it !in 4..8 }.joinToString(prefix = "(", postfix = ")")

    // Concatenating the sliced substring and tuple as a single string
    return "$slicedSubstring$numTuple"
