fun minMeetingRooms(meetings: List<Meeting>): Int {
    if (meetings.isEmpty()) {
        return 0
    }

    val startTimes = meetings.map { it.start }.sorted()
    val endTimes = meetings.map { it.end }.sorted()

    var roomsNeeded = 0
    var endIndex = 0

    for (startTime in startTimes) {
        if (startTime < endTimes[endIndex]) {
