fun compare(a: JsonArray, b: JsonArray, pos: Int = 0): Boolean? {
    val left = a.elementAtOrNull(pos)
    val right = b.elementAtOrNull(pos)
    return when {
        left == null && right == null -> null
        left == null || right == null -> left == null
        left is JsonPrimitive && right is JsonPrimitive -> if (left == right) compare(a, b, pos + 1) else left.int < right.int
        left is JsonArray && right is JsonArray -> compare(left, right) ?: compare(a, b, pos + 1)
        left is JsonPrimitive && right is JsonArray -> compare(JsonArray(listOf(left)), right) ?: compare(a, b, pos + 1)
        left is JsonArray && right is JsonPrimitive -> compare(left, JsonArray(listOf(right))) ?: compare(a, b, pos + 1)
        else -> throw IllegalStateException("$left $right")
    }
};0

fun calculateProgramOutput(program: List<Int>) = calculateOpcodes(program.toMutableList())[0]

fun calculateOpcodes(prg: MutableList<Int>): List<Int> {
    loop@ for (ip in (0 until prg.size) step 4) {
        when {
            prg[ip] == OPCODE_ADD  -> prg[prg[ip + 3]] = prg[prg[ip + 1]] + prg[prg[ip + 2]]
            prg[ip] == OPCODE_MUL  -> prg[prg[ip + 3]] = prg[prg[ip + 1]] * prg[prg[ip + 2]]
            prg[ip] == OPCODE_EXIT -> break@loop
            else                   -> throw IllegalArgumentException("Unexpected data at position $ip: ${prg[ip]}")
        }
    }
    return prg
};0

fun shortestPath(grid: Array<IntArray>, k: Int): Int {
    val m = grid.size
    val n = grid[0].size
    val visited = Array(grid.size) { Array(grid[0].size) { IntArray(grid[0].size * grid.size + 1) } }
    val queue: Queue<IntArray> = LinkedList()
    queue.add(intArrayOf(0, 0, k, 0))
    while (!queue.isEmpty()) {
        val current = queue.poll()
        val i = current[0]
        val j = current[1]
        val currentRemain = current[2]
        val currentDist = current[3]
        if (visited[i][j][currentRemain] == 1) continue
        visited[i][j][currentRemain] = 1
        if (i == m - 1 && j == n - 1) return currentDist
        for (direction in directions) {
            val newI = i + direction[0]
            val newJ = j + direction[1]
            if (newI in 0 until m && newJ in 0 until n) {
                if (grid[newI][newJ] == 1 && currentRemain > 0) {
                    queue.add(intArrayOf(newI, newJ, currentRemain - 1, currentDist + 1))
                } else if (grid[newI][newJ] == 0) {
                    queue.add(intArrayOf(newI, newJ, currentRemain, currentDist + 1))
                }
            }
        }

    }
    return -1
};0

