/**
 * Calculate the total electricity consumption for each day and store it in a dictionary.
 *
 * @param consumptionData A dictionary containing the electricity consumption data of each room for each day.
 * @return A dictionary containing the total electricity consumption for each day.
 */
fun calculateTotalElectricityConsumption(consumptionData: Map<String, Map<String, Int>>): Map<String, Int> {

    val totalConsumption = mutableMapOf<String, Int>()

    // Iterating over each day in the consumption data
    for ((day, rooms) in consumptionData) {
        // Initializing the total consumption for the current day
        var dayConsumption = 0

        // Iterating over each room in the consumption data for the current day
        for ((_, consumption) in rooms) {
            // Accessing the electricity consumption for the current room and adding it to the total consumption for the day
            dayConsumption += consumption
        }

        // Storing the total consumption for the current day in the dictionary
        totalConsumption[day] = dayConsumption
    }

    return totalConsumption
}

