fun compareArrays(
    left: JsonArray<*>,
    right: JsonArray<*>
): Boolean? {
    var i = 0
    while (true) {
        var comparison: Boolean? = null
        if (i >= left.size && i < right.size) {
            // left ran out of values first
            return true
        } else if (i < left.size && i >= right.size) {
            // right ran out of values first
            return false
        } else if (i >= left.size) {
            // no decision
            return null
        }
        val leftValue = left[i]
        val rightValue = right[i]
        when {
            leftValue is Int && rightValue is Int -> {
                comparison = compare(leftValue, rightValue)
            }

            leftValue is JsonArray<*> && rightValue is JsonArray<*> -> {
                comparison = compareArrays(leftValue, rightValue)
            }

            leftValue is Int && rightValue is JsonArray<*> -> {
                comparison = compareArrays(JsonArray(listOf(leftValue)), rightValue)
            }

            leftValue is JsonArray<*> && rightValue is Int -> {
                comparison = compareArrays(leftValue, JsonArray(listOf(rightValue)))
            }
        }
        if (comparison != null) {
            println("Compare $leftValue vs $rightValue: $comparison")
            return comparison
        }
        i++
    }
};0

fun List<Int>.linearCaloriesOfTop(n: Int): Int {
    fun findTopN(n: Int, element: List<Int>): List<Int> {
        if (element.size == n) return element
        val x = element.random()
        val small = element.filter { it < x }
        val equal = element.filter { it == x }
        val big = element.filter { it > x }
        if (big.size >= n) return findTopN(n, big)
        if (equal.size + big.size >= n) return (equal + big).takeLast(n)
        return findTopN(n - equal.size - big.size, small) + equal + big
    }
    return findTopN(n, this).sum()
};0

fun shortestPaths(graph: Graph, constraint: (height: Int, neighbourHeight: Int) -> Boolean) {
    while (graph.nodes.isNotEmpty()) {
        val node = graph.nodes.minBy { (i, j) -> graph.distances[i][j] }
        graph.nodes.remove(node)
        val (i, j) = node
        val currentHeight = graph.heights[i][j]
        val neighbourNodes = setOfNotNull(
            graph.nodes.firstOrNull { it == i + 1 to j },
            graph.nodes.firstOrNull { it == i - 1 to j },
            graph.nodes.firstOrNull { it == i to j + 1 },
            graph.nodes.firstOrNull { it == i to j - 1 },
        )
        neighbourNodes.forEach { (x, y) ->
            if (constraint(
                    currentHeight,
                    graph.heights[x][y]
                ) && graph.distances[i][j] + 1 < graph.distances[x][y]
            ) {
                graph.distances[x][y] = graph.distances[i][j] + 1
                graph.predecessors[x][y] = i to j
            }
        }
    }
};0

