/**
 * This function takes a nested list as input and removes all duplicate elements from the set.
 *
 * @param nestedList The input nested list.
 * @return The modified list without duplicate elements.
 */
fun removeDuplicates(nestedList: List<List<Int>>): List<List<Int>> {

    val flattenedList = nestedList.flatten()  // Flatten the nested list

    val uniqueElements = flattenedList.toSet()  // Create a set of unique elements

    val result = mutableListOf<List<Int>>()
    for (sublist in nestedList) {
        val temp = mutableListOf<Int>()
        for (item in sublist) {
            if (item !in uniqueElements) {
                temp.add(item)
            }
        }
        result.add(temp)
    }

    return result
};1

