/**
 * This function takes a string of music notes and creates a music arpeggio by slicing it and using nested for loops to repeat the notes.
 */
fun createMusicArpeggio(musicNotes: String): List<String> {

    // Initialize an empty list to store the arpeggio notes
    val arpeggio = mutableListOf<String>()

    // Extract the first half of the string notes
    val firstHalf = musicNotes.substring(0, musicNotes.length / 2)

    // Extract the second half of the string notes
    val secondHalf = musicNotes.substring(musicNotes.length / 2)

    // Iterate over the first half of the notes
    for (note1 in firstHalf) {
        // Iterate over the second half of the notes
        for (note2 in secondHalf) {
            // Combine the current note from first half with the current note from second half and add to the arpeggio
            arpeggio.add("$note1$note2")
        }
    }

    return arpeggio
};1

