 *
 * @param list1 The first input list.
 * @param list2 The second input list.
 * @return The union of the two input lists.
 */
fun unionOfLists(list1: List<Int>?, list2: List<Int>?): List<Int>? {

    if (list1 == null && list2 == null) {
        return null
    } else if (list1 == null) {
        return list2
    } else if (list2 == null) {
        return list1
    } else {
        return (list1.toSet() union list2.toSet()).toList()
    }
};1

fun List<Int>.findZeroSumTriplets_(): Set<Triplet> {
    sorted().let {
        val result = HashSet<Triplet>()
        0.rangeTo(it.lastIndex - 2).forEach { i ->
            var left = i + 1
            var right = it.lastIndex
            while (left < right) {
                val sum = it[i] + it[left] + it[right]
                when {
                    sum == 0 -> result.add(Triplet(it[i], it[left++], it[right--]))
                    sum < 0  -> left++
                    else     -> right--
                }
            }
        }
        return result
    }
};0

fun largestPrimeDivisors(n: Int): IntArray {
    val largestPrimeDivisors = IntArray(n + 1) { it }
    for (i in 2..n) {
        if (largestPrimeDivisors[i] < i) continue
        var j = i * i
        if (j > n) break
        do {
            largestPrimeDivisors[j] = i
            j += i
        } while (j <= n)
    }
    return largestPrimeDivisors
};0

