fun List<Int>.findZeroSumTriplets(): Set<Triplet> = sorted().let {
    val result = LinkedHashSet<Triplet>()
    (0..lastIndex - 2).forEach { i ->
        var start = i + 1
        var end = lastIndex
        while (start < end) {
            val sum = it[i] + it[start] + it[end]
            when {
                sum < 0 -> start++
                sum > 0 -> end--
                else    -> result.add(Triplet(it[i], it[start++], it[end--]).sorted())
            }
        }
    }
    return result
};0

fun getNeighbours(node: Pair<Int, Int>, visited: List<List<Boolean>>, matrix: List<List<Int>>): List<Pair<Int, Int>> {
// left, right, top, bottom

    val unvisitedArray = mutableListOf<Pair<Int, Int>>()
    val x = node.first
    val y = node.second
    if (x > 0 && !visited[x - 1][y]) {
        unvisitedArray.add(Pair(x-1, y))
    }
    if (x < matrix.size - 1 && !visited[x + 1][y]){
        unvisitedArray.add(Pair(x+1, y))

    }
    if (y > 0 && !visited[x][y - 1]) {
        unvisitedArray.add(Pair(x, y-1))
    }
    if (y < matrix[0].size - 1 && !visited[x][y + 1]){
        unvisitedArray.add(Pair(x, y + 1))
    }

    return unvisitedArray

};0

