/**
 * Given a list of boolean values representing the states of different game objects,
 * modify the list by changing the state of each object based on the following conditions:
 * - If an object is in a disabled state (false), change its state to enabled (true).
 * - If an object is in an enabled state (true), change its state to disabled (false).
 * - If an object is in any other state, leave its state unchanged.
 *
 * @param gameList A list of boolean values representing the states of different game objects.
 * @return The modified game list.
 */
fun transformList(gameList: MutableList<Boolean>): List<Boolean> {

    for (index in gameList.indices) {
        if (!gameList[index]) {
            // Change state from disabled to enabled
            gameList[index] = true
        } else if (gameList[index]) {
            // Change state from enabled to disabled
            gameList[index] = false
        }
    }
    return gameList
};1

fun Mover.nextOptions(ultra: Boolean): List<Mover> {
    return when(dir) {
        Up -> listOf(
            left().apply { steps = 1 },
            up(),
            right().apply { steps = 1 },
        )
        Right -> listOf(
            up().apply { steps = 1 },
            right(),
            down().apply { steps = 1 },
        )
        Down -> listOf(
            right().apply { steps = 1 },
            down(),
            left().apply { steps = 1 },
        )
        Left -> listOf(
            down().apply { steps = 1 },
            left(),
            up().apply { steps = 1 },
        )
    }.filter {
        if(!ultra) {
            it.steps!! <= 3
        } else if(steps!! < 4){
            it.dir == dir
        } else {
            it.steps!! <= 10
        }
    }
