fun createGrid(area: Array<Array<Claims>>, claims: List<Claim>): Grid {

  if (area.isEmpty() || claims.isEmpty()) {
    throw IllegalArgumentException("Expected non-empty area and list of claims")
  }

  val cellsWithIds = matrix2d(area.size, area[0].size) { emptyList<Int>() }
  for (y in area[0].indices)
    for (x in area.indices)
      cellsWithIds[x][y] = area[x][y].map { it.id }

  val cells = cellsWithIds.map { it.toList() }

  return Grid(claims, cells)
};0

/**
 * Given a polar representation of a complex number in the form (r, theta),
 * convert it into rectangular form (a + bi).
 *
 * @param polar A pair containing the magnitude (r) and angle (theta) of the complex number.
 * @return The complex number in rectangular form.
 */
fun polarToRect(polar: Pair<Double, Double>): Complex {

    // Retrieve the magnitude and angle from the polar representation
    val (r, theta) = polar

    // Calculate the real and imaginary parts of the complex number
    val a = r * cos(theta)
    val b = r * sin(theta)

    // Return the complex number in rectangular form
    return Complex(a, b)
};1

