/**
 * This function takes a dictionary of species records and a list of species to find,
 * and returns the records of the species that match the given list.
 */
fun findSpecies(records: Map<String, Map<String, Any>>, speciesToFind: List<String>): Map<String, Any> {

    val matchedSpecies = mutableMapOf<String, Any>()

    for (species in speciesToFind) {
        if (records.containsKey(species)) {
            if (records[species]?.get("type") == "mammal") {
                if (records[species]?.get("endangered") == true) {
                    matchedSpecies[species] = records[species]!!
                }
            }

            if (records[species]?.get("type") == "bird") {
                if (records[species]?.containsKey("wings") == true) {
                    matchedSpecies[species] = records[species]!!
                }
            }
        } else {
            matchedSpecies[species] = "Species '$species' not found."
        }
    }

    return matchedSpecies
}

