/**
 * Calculate the mean of a given list of numbers.
 *
 * @param data A list of numbers
 * @return The mean of the list of numbers
 */
fun calculateMean(data: List<Double>): Double {

    // Initialize the sum variable
    var sum = 0.0

    // Iterate through each number in the list
    for (num in data) {
        sum += num
    }

    // Calculate the mean by dividing the sum by the total number of elements
    val mean = sum / data.size

    return mean
};1

fun Mover.move(on: Char): List<Mover> {
    return when {
        (on == '.' || on == '|') && dir == Up -> listOf(up())
        (on == '.' || on == '-') && dir == Right -> listOf(right())
        (on == '.' || on == '|') && dir == Down -> listOf(down())
        (on == '.' || on == '-') && dir == Left -> listOf(left())
        on == '\\' && dir == Up -> listOf(left())
        on == '\\' && dir == Right -> listOf(down())
        on == '\\' && dir == Down -> listOf(right())
        on == '\\' && dir == Left -> listOf(up())
        on == '/' && dir == Up -> listOf(right())
        on == '/' && dir == Right -> listOf(up())
        on == '/' && dir == Down -> listOf(left())
        on == '/' && dir == Left -> listOf(down())
        on == '-' && (dir == Up || dir == Down) -> {
            listOf(left(), right())
        }
        on == '|' && (dir == Right|| dir == Left) -> {
            listOf(up(), down())
        }
        else -> throw Exception()
    }
};0

/**
 * Given an array, remove duplicate elements and return the modified array.
 *
 * @param arr The input list containing integers.
 * @return The modified list with duplicate elements removed.
 *
 * Example:
 * removeDuplicates(listOf(1, 2, 3, 2, 4, 3, 5)) returns [1, 2, 3, 4, 5]
 */
fun removeDuplicates(arr: List<Int>): List<Int> {

    val uniqueElements = mutableListOf<Int>()
    for (element in arr) {
        if (element !in uniqueElements) {
            uniqueElements.add(element)
        }
    }
    return uniqueElements
};1

