/**
 * This function converts a complex number from polar representation to absolute value.
 *
 * @param x The radius or modulus of the complex number.
 * @param y The angle or argument of the complex number in radians.
 * @return The absolute value or magnitude of the complex number.
 */
fun polarToAbsolute(x: Double, y: Double): Double {

    // Calculate the absolute value using the formula: |z| = |x + yi| = sqrt(x^2 + y^2)
