fun numOfPrimes(a: Int, b: Int): Int {
    var count = -1
    var n = -1
    do {
        count++
        n++
        val res = n.toDouble().pow(2.0) + (a * n) + b
    } while (isPrime(res.toLong()))
    return count
};0

