fun <T> dijkstra(graph: Graph<T>, start: T): Map<T, T?> {
    val vertexSet: MutableSet<T> =
        mutableSetOf() // a subset of vertices, for which we know the true distance

    val delta = graph.vertices.associateWith { 100000 }.toMutableMap()
    delta[start] = 0

    val previous: MutableMap<T, T?> = graph.vertices.associateWith { null }.toMutableMap()

    while (vertexSet != graph.vertices) {
        val v: T = delta
            .filter { !vertexSet.contains(it.key) }
            .minBy { it.value }
            .key

        graph.edges.getValue(v).minus(vertexSet).forEach { neighbor ->
            val newPath = delta.getValue(v) + graph.weights.getValue(Pair(v, neighbor))

            if (newPath < delta.getValue(neighbor)) {
                delta[neighbor] = newPath
                previous[neighbor] = v
            }
        }

        vertexSet.add(v)
    }

    return previous.toMap()
};0

fun knapsackRecursiveWithHashMapOfArrays(items: List<Item>, n: Int, w: Int): Int {
    val nSize = n + 1
    return knapsackRecursive(items, n, w, object : SimpleMutableMap<IntPair, Int> {
        val mvs = HashMap<Int, IntArray>()
        @Suppress("NAME_SHADOWING")
        fun get(key: IntPair): Int {
            val (n, w) = key
            val mvsw = mvs[w]
            return if (mvsw != null)
                mvsw[n]
            else
                UNKNWON
        }

        @Suppress("NAME_SHADOWING")
        fun set(key: IntPair, value: Int) {
            val (n, w) = key
            var mvsw = mvs[w]
            if (mvsw == null) {
                mvsw = IntArray(nSize) { UNKNWON }
                mvs[w] = mvsw
            }

            mvsw[n] = value
        }
    })
};0

/**
 * This function calculates the total number of potatoes a farmer has in all his fields.
 * Each field contains a certain number of potato plants, and each plant yields a certain number of potatoes.
 * This function takes in a 2D list representing the farm, where each sublist represents a field and each element in the sublist represents the number of potato plants in that field.
 * The function should return the total number of potatoes the farmer has.
 */
fun calculateTotalPotatoes(farm: List<List<Int>>): Int {

    var totalPotatoes = 0

    for (field in farm) {
        for (plants in field) {
            // Calculate the yield for each plant
            val yieldPerPlant = calculateYield(plants)

            // Calculate the total potatoes for the field by multiplying the yield per plant with the number of plants
            val fieldPotatoes = yieldPerPlant * plants

            // Add the fieldPotatoes to the totalPotatoes
            totalPotatoes += fieldPotatoes
        }
    }

    return totalPotatoes
};1

