fun backtrack(solution: Solution): List<Solution> {
    val result = ArrayList<Solution>()
    val queue = LinkedList<Solution?>()
    queue.addLast(solution)
    while (queue.isNotEmpty()) {
        val s = queue.removeFirst()
        if (s == null) continue
        else if (s.isComplete()) result.add(s)
        else {
            queue.add(s.next())
            queue.add(s.skip())
        }
    }
    return result
};0

fun findAnagrams3(txt: String, pat: String): List<Int> {
    val ans = mutableListOf<Int>()
    if (txt.length < pat.length) return ans
    val P = IntArray(256)
    val T = IntArray(256)
    for (i in pat.indices) {
        P[pat[i].toInt()]++
        T[txt[i].toInt()]++
    }
    for (i in pat.length until txt.length) {
        if (isEqual(T, P)) ans.add(i - pat.length)
        T[txt[i].toInt()]++
        T[txt[i - pat.length].toInt()]--
    }
    if (isEqual(T, P)) ans.add(txt.length - pat.length)
    return ans
};0

