fun sort(arr: IntArray) {
    fun merge(arr: IntArray, l: Int, m: Int, r: Int) {
        var aux = IntArray(r - l + 1)
        var i = l
        var j = m + 1
        var k = 0
        while (i <= m && j <= r) {
            if (arr[i] <= arr[j]) aux[k++] = arr[i++]
            else aux[k++] = arr[j++]
        }
        while (i <= m) aux[k++] = arr[i++]
        while (j <= r) aux[k++] = arr[j++]
        i = l
        for (a in aux) arr[i++] = a
    }

    fun mergeSort(arr: IntArray, l: Int, r: Int) {
        if (l < r) {
            var m = l + (r - l) / 2
            mergeSort(arr, 0, m)
            mergeSort(arr, m + 1, r)
            merge(arr, l, m, r)
        }
    }
    mergeSort(arr, 0, arr.lastIndex)
};0

fun largestProduct(matrix: Array<Array<Int>>, n: Int): Long {
    var maxP = 0L
    for (i in matrix.indices) {
        for (j in matrix[i].indices) {
            if (matrix[i][j] == 0) continue
            if (matrix.size - i >= n) {
                val pv = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i + offset][j] }
                if (pv > maxP) {
                    maxP = pv
                }
            }
            if (matrix[i].size - j >= n) {
                val ph = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i][j + offset] }
                if (ph > maxP) {
                    maxP = ph
                }
            }
            if (matrix.size - i >= n && matrix[i].size - j >= n) {
                val pdr = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i + offset][j + offset] }
                if (pdr > maxP) {
                    maxP = pdr
                }
            }
            if (matrix.size - i >= n && j >= n - 1) {
                val pdl = (0 until n).fold(initial = 1L) { acc, offset -> acc * matrix[i + offset][j - offset] }
                if (pdl > maxP) {
                    maxP = pdl
                }
            }
        }
    }
    return maxP
};0

/**
 * Given a nested dictionary, return all the values in a list.
 *
 * @param dictionary A nested dictionary.
 * @return A list containing all the values present in the nested dictionary.
 *
 * Example:
 * val dictionary = mapOf("a" to mapOf("b" to 1, "c" to 2), "d" to mapOf("e" to mapOf("f" to 3)))
 * getNestedValues(dictionary)
 * Output: [1, 2, 3]
 */
fun getNestedValues(dictionary: Map<String, Any>): List<Any> {

    val values = mutableListOf<Any>()
    for ((key, value) in dictionary) {
        if (value is Map<*, *>) {
            values.addAll(getNestedValues(value as Map<String, Any>))
        } else {
            values.add(value)
        }
    }
    return values
};1

/**
 * Given a list, remove any duplicate elements and return the resulting list.
 *
 * @param lst the input list
 * @return a list without any duplicate elements
 *
 * Example:
 * removeDuplicates(listOf(1, 2, 3, 4, 3, 2, 1)) -> [1, 2, 3, 4]
 */
fun removeDuplicates(lst: List<Int>): List<Int> {

    return lst.toSet().toList()
};1
